int x = Math.max(0, Math.min(1, sourceImage.getWidth() - 1));
int y = Math.max(0, Math.min(2, sourceImage.getHeight() - 1));
int cropW = sourceImage.getWidth() - x;
int cropH = sourceImage.getHeight() - y;

net.coobird.thumbnailator.geometry.Coordinate coord = new net.coobird.thumbnailator.geometry.Coordinate(x, y);
java.awt.Point p = coord.calculate(sourceImage.getWidth(), sourceImage.getHeight(), cropW, cropH, 0, 0, 0, 0);

assert p.x == x : "Coordinate x mismatch";
assert p.y == y : "Coordinate y mismatch";

java.awt.image.BufferedImage result = net.coobird.thumbnailator.Thumbnails.of(sourceImage)
    .sourceRegion(coord, new net.coobird.thumbnailator.geometry.AbsoluteSize(cropW, cropH))
    .size(cropW, cropH)
    .asBufferedImage();

assert result.getWidth() == cropW : "Result width should be " + cropW;
assert result.getHeight() == cropH : "Result height should be " + cropH;

System.out.println("__CHECK__ Coordinate " + p.x + "," + p.y + " region " + cropW + "x" + cropH);

